<script module lang="ts">
/**
 * Lines of output that follow the newest line (`design/components/log-view.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/log-view.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { Icon, followEnd, joinSlot, jumpToEnd, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/log-view.module.css'
import Button from '../controls/Button.svelte'

export interface LogLine {
  /** Unique in the log and the same on every render: the line's key. */
  id: string
  /** The line as it was written. Whitespace is content. */
  text: string
  /** How serious the line is, drawn as a marker and read as a word. */
  level?: 'info' | 'warning' | 'error'
  /** When the line was written, already formatted by the application. */
  time?: string
  /** What wrote the line, such as a service, a process or a build step. */
  source?: string
}

export interface LogViewMessages {
  /** The label of the button that returns the reader to the newest line. */
  jumpToLatest: string
  /** Read before a line whose level is `info`. */
  info: string
  /** Read before a line whose level is `warning`. */
  warning: string
  /** Read before a line whose level is `error`. */
  error: string
}

export interface LogViewProps {
  /**
   * The log's accessible name, such as "Build output" in the app's language.
   */
  label: string
  /**
   * The lines to show, oldest first. The application trims the old ones.
   */
  lines: LogLine[]
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: LogViewMessages
  /**
   * Whether more lines are coming, which draws a caret after the last line and sets `aria-busy`.
   */
  streaming?: boolean
  /**
   * Whether a long line wraps, which is the default. `false` keeps each line on one row and
   * scrolls the log sideways, for output whose columns line up.
   */
  wrap?: boolean
}
</script>

<script lang="ts">
let {
  label: labelOwn,
  lines,
  messages = (() => ({
    jumpToLatest: 'Jump to latest',
    info: 'info',
    warning: 'warning',
    error: 'error',
  }))(),
  streaming = false,
  wrap = true,
}: LogViewProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let detached = $state(false)
let overflowing = $state(false)
let list = $state<HTMLElement | null>(null)
let viewport = $state<HTMLElement | null>(null)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = followEnd(viewport, list, (state) => {
    detached = state.detached
    overflowing = state.overflowing
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.root}
    data-state={(detached) ? 'detached' : undefined}
    data-streaming={(streaming) ? '' : undefined}
    data-wrap={(wrap) ? '' : undefined}
    data-member="log-view"
    ><div
      bind:this={viewport}
      class={styles.viewport}
      data-log-view-part="viewport"
      role="log"
      aria-label={label}
      aria-live="off"
      aria-busy={(streaming) ? true : undefined}
      tabindex={((overflowing) ? '0' : undefined) as never}
      ><ol bind:this={list} class={styles.lines} role="list"
        >{#each lines as line (line.id)
          }<li class={styles.line} data-level={line.level}
            ><span class={styles.marker} aria-hidden="true"
              >{#if line.level !== undefined}<Icon name={line.level} size="sm" />{/if
            }</span
            >{#if line.level !== undefined
              }<span class={styles.spoken}>{messages[line.level] + ' '}</span
            >{/if
            }{#if line.time !== undefined}<span class={styles.time}>{line.time + ' '}</span>{/if
            }<span class={styles.text}
              >{#if line.source !== undefined
                }<span class={styles.source}>{line.source + ' '}</span
              >{/if
              }<span>{line.text}</span
            ></span
          ></li
        >{/each
        }{#if streaming
          }<li class={styles.end} aria-hidden="true"><span class={styles.caret}></span></li
        >{/if
      }</ol
    ></div
    ><div class={styles.jump}
      ><span class={styles.backing}
        ><Button
          variant="outline"
          tone="neutral"
          size="sm"
          icon="down"
          label={messages.jumpToLatest}
          onClick={() => { jumpToEnd(viewport) }}
      /></span
    ></div
  ></div
>{/if
}{@render joined.end?.()}
